        {"영어원문":"When God makes a full end, he sweeps clean; he takes away all the filth and all the filthy.", "한국어번역":"하나님이 완전히 끝내실 때 깨끗이 쓸어버리시니 모든 더러운 것과 더러운 자를 다 제하신다.", "핵심통찰":"하나님의 심판은 철저하여 남김이 없다"}
