        {"영어원문":"Those that put on strange apparel, conformed to the fashions of the heathen, showed that they had forgotten their God.", "한국어번역":"이방의 의복을 입은 자들은 이방의 풍속에 동화되어 자기 하나님을 잊었음을 드러냈다.", "핵심통찰":"외적인 세속화는 내적인 하나님 망각의 표현이다"},
        {"영어원문":"Princes should be examples of piety, not of profaneness; their sins are public and their influence extensive.", "한국어번역":"방백들은 경건의 모범이 되어야지 불경건의 모범이 되어서는 안 된다. 그들의 죄는 공개적이고 그 영향력은 광범위하다.", "핵심통찰":"지도자의 죄는 개인의 죄를 넘어 공동체 전체에 영향을 미친다"}
