        {"교리":"은혜의 거부", "설명":"하나님이 주시는 말씀, 교훈, 신뢰의 초대, 친밀함의 기회를 모두 거부하는 것은 은혜 자체를 거부하는 것", "관련구절":"히 12:25, 잠 1:24-26, 호 11:1-2, 사 65:2"},
        {"교리":"하나님께 나아감의 신학", "설명":"카라브(나아가다)는 제사적 용어로 예배와 관계의 핵심. 하나님께 나아가지 않는 것은 언약 관계의 단절", "관련구절":"히 10:22, 약 4:8, 시 73:28, 신 4:7"}
