        {"구분":"하나님께 나아가지 않음", "내용":"예배와 교제를 거부한 백성", "그리스도연결":"수고하고 무거운 짐 진 자들아 내게로 오라 하신 그리스도 (마 11:28)"},
        {"구분":"여호와를 의뢰하지 않음", "내용":"인간적 힘에 의존한 유다", "그리스도연결":"내가 곧 길이요 진리요 생명이니 나로 말미암지 않고는 아버지께 올 자가 없느니라 (요 14:6)"}
