    표2_역사적배경: [
        {"항목":"하나님의 조건부 약속", "내용":"하나님이 경외와 교훈의 수용을 조건으로 예루살렘의 보존을 약속하셨으나 백성이 이를 거부. 조건부 언약의 전형적 패턴", "목회적활용":"하나님의 은혜에는 응답의 책임이 따른다"},
        {"항목":"부지런한 악행", "내용":"히쉬키무(일찍 일어나)는 열심을 나타냄. 백성이 선한 일에는 게으르나 악한 일에는 부지런했다는 비극적 아이러니", "목회적활용":"열심의 방향이 잘못되면 더 큰 파괴를 가져온다"},
        {"항목":"예루살렘의 기회 상실", "내용":"하나님이 열국의 심판을 보여주며 회개의 기회를 주셨으나 유다는 그 기회를 놓침. 은혜의 시간을 낭비함", "목회적활용":"하나님이 주시는 회개의 기회를 놓치지 말라"}
    ],
    표3_신학적의미: [
        {"교리":"조건부 은혜", "설명":"하나님의 보호와 보존은 경외와 순종이라는 조건과 연결됨. 은혜는 무조건적이나 축복의 체험에는 응답이 필요", "관련구절":"신 28:1-2, 렘 7:3-7, 사 1:19-20, 대하 7:14"},
        {"교리":"은혜의 거부", "설명":"하나님이 분명한 약속과 조건을 제시했음에도 백성이 이를 거부하고 악에 부지런한 것은 은혜에 대한 적극적 반역", "관련구절":"히 10:26-29, 롬 2:4-5, 갈 6:7-8, 히 6:4-6"},
        {"교리":"악의 부지런함", "설명":"하나님의 일에는 게으르면서 악한 일에 부지런한 것은 인간 본성의 타락을 극명하게 보여줌", "관련구절":"잠 1:16, 사 5:11, 미 2:1, 렘 11:7-8"}
    ],
    표4_예표론: [
        {"구분":"경외와 교훈의 초청", "내용":"하나님이 은혜의 조건을 제시하심", "그리스도연결":"회개하라 천국이 가까이 왔느니라 선포하신 그리스도 (마 4:17)"},
        {"구분":"거처가 보존됨의 약속", "내용":"순종하면 예루살렘이 보존되리라는 약속", "그리스도연결":"너희가 내 안에 거하면 열매를 많이 맺으리라 약속하신 그리스도 (요 15:5)"},
        {"구분":"부지런히 악행을 더럽힘", "내용":"은혜를 거부하고 악에 열심인 백성", "그리스도연결":"예루살렘아 내가 몇 번이나 모으려 했으나 너희가 원하지 않았다 탄식하신 그리스도 (마 23:37)"}
    ],
    표5_매튜헨리: [
        {"영어원문":"I said, Surely thou wilt fear me, thou wilt receive instruction; so their dwelling should not be cut off.", "한국어번역":"내가 이르기를 분명 나를 경외하고 교훈을 받으리라 그리하면 그 거처가 끊어지지 않으리라 하였다.", "핵심통찰":"하나님의 합리적 기대와 인간의 비합리적 거부"},
        {"영어원문":"But they rose early and corrupted all their doings; they were diligent to do evil.", "한국어번역":"그러나 그들은 일찍 일어나 모든 행위를 더럽혔으니 악을 행하는 데 부지런했다.", "핵심통찰":"선에는 게으르고 악에는 부지런한 인간의 비극"},
        {"영어원문":"God expected that his judgments upon others would be a warning to them, but they disappointed his expectation.", "한국어번역":"하나님은 다른 이들에 대한 심판이 그들에게 경고가 되리라 기대하셨으나 그들이 그 기대를 저버렸다.", "핵심통찰":"하나님의 기대를 저버리는 것이 가장 큰 실망"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"거절된 은혜 - 경외와 교훈을 받으라", "예화_적용":"하나님의 은혜를 거절할 때 남는 것은 심판뿐"},
        {"대지":"서론", "내용":"하나님은 예루살렘에 두 가지를 요구하셨다. 나를 경외하라, 교훈을 받으라. 그러면 거처가 보존될 것이다. 그러나 백성은 이 단순한 요구를 거부하고 부지런히 악행을 더럽혔다", "예화_적용":"가장 단순한 하나님의 요구를 거부하는 것이 가장 큰 비극"},
        {"대지":"1대지: 나를 경외하라 (하나님 중심의 삶)", "내용":"경외는 하나님을 두려워하되 사랑으로 경배하는 것. 모든 신앙의 출발점", "예화_적용":"경외함이 없는 신앙은 형식에 불과하다"},
        {"대지":"2대지: 교훈을 받으라 (겸손한 배움)", "내용":"무사르를 받는 것은 하나님의 교정을 겸손히 받아들이는 것. 고통 속의 교훈도 포함", "예화_적용":"고통 속에서도 배우는 자가 진정 지혜로운 자"},
        {"대지":"3대지: 부지런히 더럽힌 행위 (악의 열심)", "내용":"하나님의 조건을 거부하고 오히려 악에 부지런한 비극적 역설", "예화_적용":"열심의 방향을 점검하라. 무엇에 부지런한가"},
        {"대지":"결론", "내용":"하나님의 요구는 단순했다. 경외하고 교훈을 받으라. 그러면 보존될 것이다. 오늘도 같은 초청이 우리에게 주어진다. 이 은혜를 거절하지 말라", "예화_적용":"단순한 순종이 복잡한 인생의 해답이다"}
    ],
