        {"대지":"서론", "내용":"교만한 자를 제거하신 후 하나님은 곤고하고 가난한 백성을 남기신다. 세상의 눈에는 보잘것없는 이 사람들이 하나님 나라의 참된 백성이다", "예화_적용":"하나님의 선택 기준은 세상과 정반대이다"},
        {"대지":"1대지: 곤고한 백성 (고통을 통과한 자)", "내용":"아니는 고통받는 자를 의미. 삶의 고통을 통해 겸손해진 자들", "예화_적용":"고통이 우리를 겸손하게 만들 때 그것은 은혜가 된다"},
        {"대지":"2대지: 가난한 백성 (세상에 기댈 것 없는 자)", "내용":"달은 미약한 자. 세상적 자원이 없어 오직 하나님만 의지하는 자들", "예화_적용":"가진 것이 없을수록 하나님을 더 강하게 붙잡게 된다"},
        {"대지":"3대지: 여호와의 이름에 의탁함 (참된 안전)", "내용":"남은 자의 가장 중요한 특징은 여호와의 이름에 피하는 것. 하나님만이 참된 피난처", "예화_적용":"잠언 18:10 여호와의 이름은 견고한 망대라 의인은 그리로 달려가서 안전함을 얻느니라"},
        {"대지":"결론", "내용":"하나님은 교만한 다수가 아니라 겸손한 소수를 남기신다. 세상의 기준으로 보잘것없는 자가 하나님의 기준으로 가장 귀한 자이다. 곤고하고 가난하나 여호와를 의뢰하는 자가 되자", "예화_적용":"고린도전서 1:27-28 하나님이 세상의 약한 것들을 택하사 강한 것들을 부끄럽게 하려 하시며"}
