        {"원어":"כָּזָב (카자브)", "의미_문법":"거짓 - 명사. 거짓말, 속임", "설교포인트":"진실함은 하나님 백성의 근본 특성"},
        {"원어":"תַּרְמִית (타르밋)", "의미_문법":"궤휼/속임 - 명사. 기만적인 말", "설교포인트":"입술의 정직함이 내면의 거룩함을 보여준다"},
        {"원어":"מַרְבִּיץ (마르비츠)", "의미_문법":"놀라게 하다/두렵게 하다 - 분사. 위협하는 자", "설교포인트":"하나님의 백성에게는 참된 평안이 주어진다"}
