        {"구분":"거짓이 없는 입", "내용":"진실만을 말하는 백성", "그리스도연결":"그 입에 궤사가 없으시더라 하신 그리스도 (벧전 2:22, 사 53:9)"},
        {"구분":"평안히 누움", "내용":"위협 없는 완전한 평화", "그리스도연결":"내 평안을 너희에게 주노라 하신 그리스도 (요 14:27)"}
