        {"대지":"서론", "내용":"스바냐는 남은 자의 모습을 그린다. 악을 행치 않고, 거짓이 없으며, 궤휼한 혀가 없고, 완전한 평안 속에 거한다. 이것이 하나님이 꿈꾸시는 공동체의 모습이다", "예화_적용":"하나님 나라의 시민은 이렇게 산다"},
        {"대지":"1대지: 악을 행치 않음 (의로운 삶)", "내용":"남은 자의 첫 특징은 불의를 행하지 않는 것. 이전 지도자들의 포학과 대비", "예화_적용":"하지 않는 것도 중요한 신앙의 표현. 악에서 떠나라"},
        {"대지":"2대지: 거짓과 궤휼이 없음 (진실한 삶)", "내용":"거짓과 궤휼은 거짓 선지자의 특징이었다. 남은 자는 진실만을 말함", "예화_적용":"말의 진실함이 신앙의 진실함을 증명한다"},
        {"대지":"3대지: 먹고 누워도 평안함 (보호받는 삶)", "내용":"양이 목자 아래 안전하게 쉬는 모습. 위협과 공포가 사라진 완전한 평안", "예화_적용":"하나님의 보호 아래 있으면 어떤 두려움도 없다"},
        {"대지":"결론", "내용":"남은 자의 삶은 단순하다. 악을 피하고, 진실을 말하고, 하나님의 평안 안에 거하는 것. 복잡한 세상에서 이 단순한 삶이 가장 아름다운 삶이다", "예화_적용":"시편 23편의 삶을 오늘 여기서 살아가자"}
