        {"상황":"거짓말의 습관에서 벗어나지 못하는 분", "성경원리":"남은 자의 입에는 궤휼한 혀가 없다. 입술의 변화는 마음의 변화에서 시작", "실제적용":"작은 거짓말부터 멈추라. 매일 진실을 말하는 훈련을 하고 하나님께 도움을 구하라"}
