        {"구절":"눅 1:46-47", "연결점":"내 영혼이 주를 찬양하며 내 마음이 구주를 기뻐하였음은", "구분":"신약"},
        {"구절":"요 16:20-22", "연결점":"너희 근심이 도리어 기쁨이 되리라", "구분":"신약"},
        {"구절":"벧전 1:8", "연결점":"말할 수 없는 영광스러운 즐거움으로 기뻐하니", "구분":"신약"}
